-- Renames every database object whose name contains "exam" to "assessment", and the stored values
-- that carry the same word (enum-like strings, CHECK constraints, notification history).
--
-- The object names below were read from a database built by V1-V13, not guessed.
-- Everything except section 6 is a metadata rename, so no table is rewritten.
--
-- Not renamed on purpose: columns off_topic_examples and examples_json ("example", not "exam").
-- Three constraint names would exceed the 63-character identifier limit once "exam" becomes
-- "assessment"; they are shortened explicitly instead of being truncated by PostgreSQL.

-- 1. Tables

ALTER TABLE exam_blueprint_sections RENAME TO assessment_blueprint_sections;
ALTER TABLE exam_blueprint_slots RENAME TO assessment_blueprint_slots;
ALTER TABLE exam_blueprint_versions RENAME TO assessment_blueprint_versions;
