-- 6. Notification history. Only the event type column, the three renamed payload keys and the values of the
--    "eventType" and "target" keys are rewritten; every other payload value (user text such as the assessment name)
--    is left exactly as stored. Outbox rows are not rewritten: the outbox must be drained before this release.
UPDATE notifications
SET event_type = regexp_replace(event_type, '^Exam', 'Assessment')
WHERE event_type LIKE 'Exam%';

UPDATE notifications
SET payload = (
    SELECT jsonb_object_agg(
        CASE entry.key
            WHEN 'examId' THEN 'assessmentId'
            WHEN 'examKind' THEN 'assessmentKind'
            WHEN 'examName' THEN 'assessmentName'
            ELSE entry.key
        END,
        CASE
            WHEN entry.key = 'eventType' AND jsonb_typeof(entry.value) = 'string'
                THEN to_jsonb(regexp_replace(entry.value #>> '{}', '^Exam', 'Assessment'))
            WHEN entry.key = 'target' AND jsonb_typeof(entry.value) = 'string'
                THEN to_jsonb(regexp_replace(entry.value #>> '{}', '^EXAM_', 'ASSESSMENT_'))
            ELSE entry.value
        END)
    FROM jsonb_each(notifications.payload) AS entry)
WHERE jsonb_typeof(payload) = 'object'
  AND (payload ?| ARRAY['examId', 'examKind', 'examName']
       OR payload ->> 'eventType' LIKE 'Exam%'
       OR payload ->> 'target' LIKE 'EXAM\_%');

-- 7. Column comment that names the old event
COMMENT ON COLUMN assessments.human_grading_notified_at IS
    'When AssessmentHumanGradingRequired was last published for this assessment. NULL = never reminded. '
    'Guard against duplicates from the periodic sweep.';
